export const LEGENDARY_STORIES=Object.fromEntries(rows.map(([id,scene,title,location,omen,arrival,effect])=>[id,{id,scene,title,location,omen,arrival,effect,duration:FILMS[id].duration,color:({ice:'#a3e8fa',power:'#ffd56c',volcano:'#ff8c55',lab:'#d9a9ff',forest:'#8cdda0',storm:'#b9c8fd',lake:'#94dfe4',ocean:'#7dc9f3',tower:'#f8ca85',ruins:'#d5c89e',island:'#85d4d2',cosmos:'#c2b3f1',temple:'#c1cce5',distortion:'#d59ad5',moon:'#c7bbf1',flower:'#e9b6cf',origin:'#f4e4b7',cliff:'#d6bd94',field:'#afd389',theatre:'#ebbd96',cave:'#99d3b1',crystal:'#d7c5f5',desert:'#e0c08c',city:'#a8c0ff',village:'#ecb3c5','sky-pillar':'#8df4b3'})[scene],music:['ocean','volcano','storm','power','sky-pillar'].includes(scene)?'storm':['forest','flower','lake','village','field','island'].includes(scene)?'forest':'cosmic'}]));
export function normalizeStories(raw){return{seen:[...new Set((Array.isArray(raw?.seen)?raw.seen:[]).map(Number).filter(id=>LEGENDARY_STORIES[id]))],pending:[...new Map((Array.isArray(raw?.pending)?raw.pending:[]).filter(x=>x&&LEGENDARY_STORIES[+x.id]&&/^\d+s?$/.test(String(x.key))&&parseInt(x.key)===+x.id).map(x=>[+x.id,{id:+x.id,key:String(x.key)}])).values()]}}
export function reserveStories(state,results){state.legendaryStories=normalizeStories(state.legendaryStories);const known=new Set(state.roster.map(k=>parseInt(k)));for(const r of results){const id=parseInt(r.key);r.story=r.rarity==='legendary'&&!known.has(id)&&!state.legendaryStories.seen.includes(id)&&!state.legendaryStories.pending.some(p=>p.id===id)&&!!LEGENDARY_STORIES[id];if(r.story)state.legendaryStories.pending.push({id,key:r.key});known.add(id)}}
export function completeStory(state,id){state.legendaryStories=normalizeStories(state.legendaryStories);if(!state.legendaryStories.seen.includes(id))state.legendaryStories.seen.push(id);state.legendaryStories.pending=state.legendaryStories.pending.filter(p=>p.id!==id)}
